mapper.select:
SELECT w.*, g.goodsname, g.number as current_number, CASE WHEN w.type = 1 THEN g.dangernum ELSE g.maxnum END as threshold_value FROM bus_inventory_warning w LEFT JOIN bus_goods g ON w.goodsid = g.id
AND w.status = #{status}
ORDER BY w.create_time DESC

mapper.update:
UPDATE bus_inventory_warning
SET status = #{status},
    handler = #{handler},
    handle_time = NOW(),
    handle_remark = #{handleRemark}
WHERE id = #{id}
